* >Natural Source Code: LOWSTOCK
* PROGRAM: LOWSTOCK - LOW STOCK ALERT REPORT
* DESCRIPTION: IDENTIFIES PRODUCTS BELOW REORDER LEVEL
*              GENERATES RECOMMENDED PURCHASE QUANTITIES
*              LINKS TO PREFERRED SUPPLIERS
* LIBRARY: RETAILCORE
* ADABAS FILES: 105 (INVENTORY), 101 (PRODUCT), 130 (SUPPLIER)
* CREATED: 2003-07-15  A. GARCIA
* MODIFIED: 2010-11-22 - ADDED SUPPLIER INFO
* MODIFIED: 2019-04-10 - ADDED REORDER RECOMMENDATION
* -------------------------------------------------------
DEFINE DATA
LOCAL
  1 #TOTAL-LOW            (N8)
  1 #CRITICAL-COUNT       (N8)
  1 #AVAILABLE            (N8)
  1 #REORDER-QTY          (N8)
  1 #PRIORITY             (A8)
*
  1 LSR-VIEW VIEW OF INVENTORY-FILE
    2 LSR-PROD-ID          (N8)
    2 LSR-SKU              (A15)
    2 LSR-LOCATION-ID      (N6)
    2 LSR-LOCATION-TYPE    (A1)
    2 LSR-ON-HAND          (N8)
    2 LSR-RESERVED         (N8)
    2 LSR-ALLOCATED        (N8)
    2 LSR-DAMAGED          (N8)
    2 LSR-SAFETY-STOCK     (N8)
    2 LSR-REORDER-LEVEL    (N8)
    2 LSR-REORDER-QTY      (N8)
    2 LSR-STATUS           (A1)
*
  1 LPR-VIEW VIEW OF PRODUCT-FILE
    2 LPR-ID               (N8)
    2 LPR-NAME             (A60)
    2 LPR-SUPP-ID          (N8)
    2 LPR-COST-PRICE       (N9.2)
*
  1 LSP-VIEW VIEW OF SUPPLIER-FILE
    2 LSP-ID               (N8)
    2 LSP-NAME             (A60)
    2 LSP-LEAD-TIME-DAYS   (N3)
    2 LSP-STATUS           (A1)
END-DEFINE
*
* -------------------------------------------------------
* LOAD CONFIGURATION
* -------------------------------------------------------
1 #CFG-VALUE   (A80)
1 #CFG-NUM     (N11.2)
1 #CFG-DATE    (D)
1 #CFG-FLAG    (A1)
1 #CFG-FOUND   (A1)
1 #SAFETY-DEFAULT (N8) INIT <10>
*
CALLNAT 'CONFIGN' 'SAFETY.STOCK.DEFAULT'
  #CFG-VALUE #CFG-NUM #CFG-DATE #CFG-FLAG #CFG-FOUND
IF #CFG-FOUND = 'Y'
  MOVE #CFG-NUM TO #SAFETY-DEFAULT
END-IF
*
CALLNAT 'CONFIGN' 'INV.LOWSTOCK.REPORT.MAX'
  #CFG-VALUE #CFG-NUM #CFG-DATE #CFG-FLAG #CFG-FOUND
1 #MAX-ITEMS (N8) INIT <10000>
IF #CFG-FOUND = 'Y'
  MOVE #CFG-NUM TO #MAX-ITEMS
END-IF
*
* FORMAT REPORT DATE
1 #DT-VALID   (A1)
1 #DT-ERR     (A60)
1 #DT-RESULT  (D)
1 #DT-STR     (A10)
1 #DT-NUM     (N5)
1 #RUN-DATE   (D)
MOVE *DATX TO #RUN-DATE
CALLNAT 'DATEU' 'FMT' #RUN-DATE #RUN-DATE 0 #DT-RESULT
  #DT-STR #DT-NUM #DT-VALID #DT-ERR
*
WRITE 'RETAILCORE - LOW STOCK ALERT REPORT'
WRITE '===================================='
WRITE 'RUN DATE:' #DT-STR
WRITE ' '
WRITE 'PRIORITY PRODUCT  SKU             LOC   AVAIL  SAFETY REORDER'
  ' REC-QTY SUPPLIER                      LEAD'
WRITE '-------- -------- --------------- ----- ------ ------ -------'
  ' ------- ----------------------------- ----'
*
READ LSR-VIEW BY LSR-PROD-ID
  IF LSR-STATUS NE 'A'
    ESCAPE TOP
  END-IF
*
  COMPUTE #AVAILABLE = LSR-ON-HAND - LSR-RESERVED
    - LSR-ALLOCATED - LSR-DAMAGED
  IF #AVAILABLE < 0
    MOVE 0 TO #AVAILABLE
  END-IF
*
  * CHECK IF BELOW REORDER
  IF LSR-REORDER-LEVEL > 0 AND #AVAILABLE < LSR-REORDER-LEVEL
    ADD 1 TO #TOTAL-LOW
*
    * DETERMINE PRIORITY
    IF #AVAILABLE = 0
      MOVE 'CRITICAL' TO #PRIORITY
      ADD 1 TO #CRITICAL-COUNT
    ELSE IF #AVAILABLE < LSR-SAFETY-STOCK
      MOVE 'URGENT  ' TO #PRIORITY
    ELSE
      MOVE 'NORMAL  ' TO #PRIORITY
    END-IF
    END-IF
*
    * CALCULATE RECOMMENDED REORDER QTY
    IF LSR-REORDER-QTY > 0
      MOVE LSR-REORDER-QTY TO #REORDER-QTY
    ELSE
      COMPUTE #REORDER-QTY = LSR-REORDER-LEVEL * 2 - #AVAILABLE
    END-IF
*
    * GET PRODUCT AND SUPPLIER INFO
    1 #PROD-NAME (A60)
    1 #SUPP-ID (N8)
    1 #SUPP-NAME (A60)
    1 #LEAD-DAYS (N3)
    RESET #PROD-NAME
    RESET #SUPP-NAME
    RESET #LEAD-DAYS
*
    FIND LPR-VIEW WITH LPR-ID = LSR-PROD-ID
      IF NO RECORDS FOUND
        IGNORE
      END-NOREC
      MOVE LPR-NAME    TO #PROD-NAME
      MOVE LPR-SUPP-ID TO #SUPP-ID
      ESCAPE BOTTOM
    END-FIND
*
    IF #SUPP-ID > 0
      FIND LSP-VIEW WITH LSP-ID = #SUPP-ID
        IF NO RECORDS FOUND
          IGNORE
        END-NOREC
        MOVE LSP-NAME           TO #SUPP-NAME
        MOVE LSP-LEAD-TIME-DAYS TO #LEAD-DAYS
        ESCAPE BOTTOM
      END-FIND
    END-IF
*
    WRITE #PRIORITY LSR-PROD-ID LSR-SKU LSR-LOCATION-ID
      #AVAILABLE LSR-SAFETY-STOCK LSR-REORDER-LEVEL
      #REORDER-QTY #SUPP-NAME (EM=XXXXXXXXXXXXXXXXXXXXXXXXXXXXX)
      #LEAD-DAYS
  END-IF
*
END-READ
*
* -------------------------------------------------------
* VERIFY CRITICAL ITEMS THROUGH INVENTORY CHECK
* -------------------------------------------------------
1 #IC-OH      (N8)
1 #IC-RES     (N8)
1 #IC-AVAIL   (N8)
1 #IC-VALID   (A1)
1 #IC-ERR     (A60)
1 #IC-VERIFIED (N6)
*
WRITE ' '
WRITE 'VERIFYING CRITICAL ITEMS...'
READ LSR-VIEW BY LSR-PROD-ID
  IF LSR-STATUS NE 'A'
    ESCAPE TOP
  END-IF
  COMPUTE #AVAILABLE = LSR-ON-HAND - LSR-RESERVED
    - LSR-ALLOCATED - LSR-DAMAGED
  IF #AVAILABLE = 0
    CALLNAT 'INVCHK' LSR-PROD-ID LSR-SKU LSR-LOCATION-ID
      LSR-LOCATION-TYPE #IC-OH #IC-RES #IC-AVAIL
      #IC-VALID #IC-ERR
    IF #IC-VALID = 'Y'
      ADD 1 TO #IC-VERIFIED
    ELSE
      CALLNAT 'LOGERR' 650 #IC-ERR 'W' 'LOWSTOCK' *USER
    END-IF
  END-IF
  IF *COUNTER > #MAX-ITEMS
    ESCAPE BOTTOM
  END-IF
END-READ
WRITE '  CRITICAL ITEMS VERIFIED:' #IC-VERIFIED
*
* -------------------------------------------------------
* VALIDATE SKUS FOR LOW-STOCK PRODUCTS
* -------------------------------------------------------
WRITE ' '
WRITE 'VALIDATING LOW-STOCK SKUs...'
1 #SKV-PROD-ID (N8)
1 #SKV-NAME    (A60)
1 #SKV-STATUS  (A1)
1 #SKV-PRICE   (N9.2)
1 #SKV-TAX     (A4)
1 #SKV-VALID   (A1)
1 #SKV-MSG     (A60)
1 #SKV-ERRORS  (N6)
*
READ LSR-VIEW BY LSR-PROD-ID
  IF LSR-STATUS NE 'A'
    ESCAPE TOP
  END-IF
  COMPUTE #AVAILABLE = LSR-ON-HAND - LSR-RESERVED
    - LSR-ALLOCATED - LSR-DAMAGED
  IF #AVAILABLE < LSR-REORDER-LEVEL AND LSR-SKU NE ' '
    CALLNAT 'SKUVAL' LSR-SKU ' ' #SKV-PROD-ID #SKV-NAME
      #SKV-STATUS #SKV-PRICE #SKV-TAX #SKV-VALID #SKV-MSG
    IF #SKV-VALID NE 'Y'
      ADD 1 TO #SKV-ERRORS
    END-IF
  END-IF
  IF *COUNTER > #MAX-ITEMS
    ESCAPE BOTTOM
  END-IF
END-READ
WRITE '  SKU ERRORS:' #SKV-ERRORS
*
* -------------------------------------------------------
* FORMAT SUMMARY NUMBERS
* -------------------------------------------------------
1 #FMT-OUT (A132)
1 #FMT-IN  (A80)
CALLNAT 'FMTU' 'PADL' #FMT-IN 0 '0' 6 #FMT-OUT
*
WRITE ' '
WRITE 'SUMMARY'
WRITE '======='
WRITE 'TOTAL LOW STOCK ITEMS:' #TOTAL-LOW
WRITE 'CRITICAL (ZERO STOCK):' #CRITICAL-COUNT
WRITE 'INVENTORY VERIFIED   :' #IC-VERIFIED
WRITE 'SKU VALIDATION ERRORS:' #SKV-ERRORS
WRITE ' '
WRITE 'END OF REPORT'
*
CALLNAT 'AUDITN' 'INV' 'LOWSTOCK' 'R' 'REPORTS'
  ' ' ' ' 'LOW STOCK REPORT GENERATED'
*
END
